SELECT promo_name, income_band, store_sales_profit, store_returns_loss, catalog_sales_profit, net_contribution, RANK() OVER (PARTITION BY income_band ORDER BY net_contribution DESC) AS promo_rank FROM ( SELECT p.p_promo_name AS promo_name, hd.hd_income_band_sk AS income_band, SUM(ss.ss_net_profit) AS store_sales_profit, SUM(COALESCE(sr.sr_net_loss, 0)) AS store_returns_loss, SUM(cs.cs_net_profit) AS catalog_sales_profit, SUM(ss.ss_net_profit) - SUM(COALESCE(sr.sr_net_loss, 0)) + SUM(cs.cs_net_profit) AS net_contribution FROM store_sales ss JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk LEFT JOIN store_returns sr ON ss.ss_ticket_number = sr.sr_ticket_number AND ss.ss_item_sk = sr.sr_item_sk AND sr.sr_hdemo_sk = hd.hd_demo_sk LEFT JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk AND cs.cs_bill_hdemo_sk = hd.hd_demo_sk WHERE p.p_start_date_sk <= 2450820 AND p.p_end_date_sk >= 2450820 AND ss.ss_sold_date_sk BETWEEN 2450815 AND 2450826 GROUP BY p.p_promo_name, hd.hd_income_band_sk ) t ORDER BY net_contribution DESC LIMIT 100
